    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]
    codes = [ord(ch) - 97 for ch in S]

    size = 1 << N

    # f[mask][j] = LCS(S[:j], current_T)
    # mask bit (j-1) is 1 iff f[j] > f[j-1]
    f_list = []
    for mask in range(size):
        f = [0] * (N + 1)
        for j in range(1, N + 1):
            f[j] = f[j - 1] + ((mask >> (j - 1)) & 1)
        f_list.append(f)

    trans = [[0] * 26 for _ in range(size)]

    for mask in range(size):
        f = f_list[mask]
        for c in range(26):
            nf = [0] * (N + 1)

            for j in range(1, N + 1):
                best = f[j]
                if nf[j - 1] > best:
                    best = nf[j - 1]
                if codes[j - 1] == c:
                    cand = f[j - 1] + 1
                    if cand > best:
                        best = cand
                nf[j] = best

            nmask = 0
            for j in range(1, N + 1):
                if nf[j] > nf[j - 1]:
                    nmask |= 1 << (j - 1)

            trans[mask][c] = nmask

    pop = [0] * size
    for i in range(size):
        pop[i] = bin(i).count("1")

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask in range(size):
