        ndp1 = [0] * (max_e + 1)

        if a == 0:
            for e in range(max_e + 1):
                v0 = dp0[e]
                v1 = dp1[e]
                if v0:
                    ndp0[e] = (ndp0[e] + v0 * powp[e]) % MOD
                if v1:
                    ndp1[e] = (ndp1[e] + v1 * powp[e]) % MOD
        else:
            for e in range(max_e + 1):
                v0 = dp0[e]
                v1 = dp1[e]
                if v0 == 0 and v1 == 0:
                    continue

                # e -> e + a
                e2 = e + a
                if e2 <= max_e:
