def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0

    N = data[idx]
    idx += 1

    intervals = []
    for _ in range(N):
        L = data[idx]
        R = data[idx + 1]
        idx += 2
        intervals.append((L, R))

    Q = data[idx]
    idx += 1
    queries = data[idx:idx + Q]

    M = 500000
    size = 4 * M + 5
    maxv = [0] * size
    lazy = [0] * size

    def build(node, l, r):
        maxv[node] = r
        if l == r:
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)

    def apply(node, val):
        maxv[node] += val
        lazy[node] += val

    def push(node):
        z = lazy[node]
        if z:
            left = node * 2
            right = left + 1
            maxv[left] += z
            lazy[left] += z
            maxv[right] += z
            lazy[right] += z
            lazy[node] = 0

    def range_add(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            maxv[node] += val
            lazy[node] += val
            return

        push(node)
        mid = (l + r) // 2

        if ql <= mid:
            range_add(node * 2, l, mid, ql, qr, val)
        if qr > mid:
            range_add(node * 2 + 1, mid + 1, r, ql, qr, val)

        maxv[node] = max(maxv[node * 2], maxv[node * 2 + 1])

    def find_first(node, l, r, x):
        if maxv[node] < x:
            return M + 1
        if l == r:
            return l

        push(node)
        mid = (l + r) // 2

        if maxv[node * 2] >= x:
            return find_first(node * 2, l, mid, x)
        else:
            return find_first(node * 2 + 1, mid + 1, r, x)

    def point_query(node, l, r, pos):
