import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ci = C[i]
        Ai = A[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ci[j] += aik * Bk[j]
        for j in range(n):
            Ci[j] %= mod
    return C

def mat_pow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1
    while e:
        if e & 1:
            R = mat_mul(R, A, mod)
        e >>= 1
        if e:
            A = mat_mul(A, A, mod)
    return R

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    p = int(data[1])

