    for i in range(2, 2 + N):
        freq[nums[i]] += 1

    cnt = [0] * (max_val + 1)
    f = freq
    M = max_val

    for d in range(1, M + 1):
        s = 0
        for m in range(d, M + 1, d):
            s += f[m]
        cnt[d] = s

    best = [0] * (M + 1)
    b = best
    c = cnt
    K_val = K

    for d in range(1, M + 1):
        if c[d] >= K_val:
            for m in range(d, M + 1, d):
                b[m] = d

    del f, c, freq, cnt

    out = '\n'.join(str(b[nums[i]]) for i in range(2, 2 + N))
    sys.stdout.write(out)

